From 44e1e3fd6ce4124f1cf1a6519d6f7ceae4aad95c Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 22:03:01 +0100
Subject: [PATCH] Folder View: Place pasted items at the pointer

Pasted files always went to the first free spot on the desktop, while
dropped files land where they are dropped. Now Ctrl+V puts them under
the pointer, and Paste from the context menu where the menu was opened.

BUG: 470922
---
 .../desktop/plugins/folder/foldermodel.cpp    | 56 ++++++++++++-------
 .../desktop/plugins/folder/foldermodel.h      |  3 +-
 2 files changed, 38 insertions(+), 21 deletions(-)

diff --git a/containments/desktop/plugins/folder/foldermodel.cpp b/containments/desktop/plugins/folder/foldermodel.cpp
index f92147ae4c..7596e91f7a 100644
--- a/containments/desktop/plugins/folder/foldermodel.cpp
+++ b/containments/desktop/plugins/folder/foldermodel.cpp
@@ -335,13 +335,13 @@ QHash<int, QByteArray> FolderModel::staticRoleNames()
     return roleNames;
 }

-QPoint FolderModel::localMenuPosition() const
+QPoint FolderModel::localPosition(const QPoint &globalPosition) const
 {
     QScreen *screen = nullptr;
-    auto position = m_menuPosition;
+    auto position = globalPosition;

     for (auto *s : qApp->screens()) {
-        if (s->geometry().contains(m_menuPosition)) {
+        if (s->geometry().contains(globalPosition)) {
             screen = s;
             break;
         }
@@ -394,7 +394,7 @@ void FolderModel::newFileMenuItemCreated(const QUrl &url)
 {
     if (m_usedByContainment && !m_screenMapper->sharedDesktops()) {
         m_screenMapper->addMapping(url, m_screen, m_currentActivity, ScreenMapper::DelayedSignal);
-        m_dropTargetPositions.insert(url.fileName(), localMenuPosition());
+        m_dropTargetPositions.insert(url.fileName(), localPosition(m_menuPosition));
         m_menuPosition = {};
         m_dropTargetPositionsCleanup->start();
     }
@@ -1489,21 +1489,7 @@ void FolderModel::drop(QQuickItem *target, QObject *dropEvent, int row, bool sho
      */
     connect(dropJob, &KIO::DropJob::copyJobStarted, this, [this, dropPos, dropTargetUrl](KIO::CopyJob *copyJob) {
         auto map = [this, dropPos, dropTargetUrl](const QUrl &targetUrl) {
-            // KIO::CopyJob::copyingDone is emitted recursively, ignore everything not directly in the target folder
-            if ((dropTargetUrl.path() + QStringLiteral("/") + targetUrl.fileName()) != targetUrl.path()) {
-                return;
-            }
-            m_dropTargetPositions.insert(targetUrl.fileName(), dropPos);
-            m_dropTargetPositionsCleanup->start();
-
-            if (m_usedByContainment && !m_screenMapper->sharedDesktops()) {
-                // assign a screen for the item before the copy is actually done, so
-                // filterAcceptsRow doesn't assign the default screen to it
-                QUrl url = resolvedUrl();
-                if (targetUrl.toString().startsWith(url.toString())) {
-                    m_screenMapper->addMapping(targetUrl, m_screen, m_currentActivity, ScreenMapper::DelayedSignal);
-                }
-            }
+            placeCreatedItem(targetUrl, dropTargetUrl, dropPos);
         };
         // remember drop target position for target URL and forget about the source URL
         connect(copyJob, &KIO::CopyJob::copyingDone, this, [map](KIO::Job *, const QUrl &, const QUrl &targetUrl, const QDateTime &, bool, bool) {
@@ -1515,6 +1501,25 @@ void FolderModel::drop(QQuickItem *target, QObject *dropEvent, int row, bool sho
     });
 }

+void FolderModel::placeCreatedItem(const QUrl &targetUrl, const QUrl &targetDirUrl, const QPoint &pos)
+{
+    // KIO::CopyJob::copyingDone is emitted recursively, ignore everything not directly in the target folder
+    if ((targetDirUrl.path() + QStringLiteral("/") + targetUrl.fileName()) != targetUrl.path()) {
+        return;
+    }
+    m_dropTargetPositions.insert(targetUrl.fileName(), pos);
+    m_dropTargetPositionsCleanup->start();
+
+    if (m_usedByContainment && !m_screenMapper->sharedDesktops()) {
+        // assign a screen for the item before the copy is actually done, so
+        // filterAcceptsRow doesn't assign the default screen to it
+        QUrl url = resolvedUrl();
+        if (targetUrl.toString().startsWith(url.toString())) {
+            m_screenMapper->addMapping(targetUrl, m_screen, m_currentActivity, ScreenMapper::DelayedSignal);
+        }
+    }
+}
+
 void FolderModel::dropCwd(QObject *dropEvent)
 {
     QMimeData *mimeData = qobject_cast<QMimeData *>(dropEvent->property("mimeData").value<QObject *>());
@@ -2311,6 +2316,9 @@ void FolderModel::cut()

 void FolderModel::paste()
 {
+    // From the context menu, paste where the menu was opened; with the keyboard, under the pointer
+    const QPoint globalPos = qobject_cast<QAction *>(sender()) ? m_menuPosition : QCursor::pos();
+
     updateActions();

     if (QAction *action = m_actionCollection.action(QStringLiteral("paste"))) {
@@ -2319,9 +2327,17 @@ void FolderModel::paste()
         }
     }

-    KIO::PasteJob *job = KIO::paste(QApplication::clipboard()->mimeData(), m_dirModel->dirLister()->url());
+    const QUrl targetDirUrl = m_dirModel->dirLister()->url();
+    KIO::PasteJob *job = KIO::paste(QApplication::clipboard()->mimeData(), targetDirUrl);
     auto delegate = new KNotificationJobUiDelegate(KJobUiDelegate::AutoHandlingEnabled);
     job->setUiDelegate(delegate);
+
+    if (m_usedByContainment && screenGeometry().contains(globalPos)) {
+        const QPoint pos = localPosition(globalPos);
+        connect(job, &KIO::PasteJob::itemCreated, this, [this, targetDirUrl, pos](const QUrl &url) {
+            placeCreatedItem(url, targetDirUrl, pos);
+        });
+    }
 }

 void FolderModel::pasteTo()
