+++ b/containments/desktop/plugins/folder/foldermodel.h
@@ -361,7 +361,8 @@ private:
         bool blank;
     };

-    QPoint localMenuPosition() const;
+    QPoint localPosition(const QPoint &globalPosition) const;
+    void placeCreatedItem(const QUrl &targetUrl, const QUrl &targetDirUrl, const QPoint &pos);
     void createActions();
     void addDragImage(QDrag *drag, int x, int y);
     void setStatus(Status status);
